import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadHygamData(){const e=readFileSync(resolve(__dirname,"../../frontend/hygam-wetland-explorer/hygam-data.js"),"utf-8");return new Function(e+"\nreturn { HYGAM_INFO, ECOLOGY_HYDROLOGY, BIRD_SPECIES, INTERESTING_FACTS, MAP_HOTSPOTS, GALLERY_IMAGES };")()}function loadWetlandsLandingData(){let e=readFileSync(resolve(__dirname,"../../frontend/wetlands/wetlands-data.js"),"utf-8");e=e.replace(/export\s+const\s+/g,"const ");return new Function(e+"\nreturn WETLANDS_DATA;")()}describe("Hygam Wetland Explorer — Data & Integration Tests",()=>{let e;beforeAll(()=>{e=loadHygamData()}),describe("HYGAM_INFO metadata",()=>{it("contains correct wetland metadata and status",()=>{expect(e.HYGAM_INFO.id).toBe("hygam-wetland"),expect(e.HYGAM_INFO.name).toContain("Hygam"),expect(e.HYGAM_INFO.ramsarYear).toBe(2022),expect(e.HYGAM_INFO.ramsarSiteNo).toBe(2489),expect(e.HYGAM_INFO.state).toBe("Jammu & Kashmir")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.HYGAM_INFO.quickStats)).toBe(!0),expect(e.HYGAM_INFO.quickStats.length).toBe(6)})}),describe("ECOLOGY_HYDROLOGY & INTERESTING_FACTS",()=>{it("contains overview, hydrology, and conservation status",()=>{expect(e.ECOLOGY_HYDROLOGY.overview).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.hydrology).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.conservationStatus).toBeDefined()}),it("contains interesting facts array",()=>{expect(Array.isArray(e.INTERESTING_FACTS)).toBe(!0),expect(e.INTERESTING_FACTS.length).toBeGreaterThanOrEqual(3)})}),describe("BIRD_SPECIES catalog",()=>{it("is a non-empty array of migratory bird species",()=>{expect(Array.isArray(e.BIRD_SPECIES)).toBe(!0),expect(e.BIRD_SPECIES.length).toBeGreaterThanOrEqual(4)}),it("includes Mallard and Northern Pintail",()=>{const t=e.BIRD_SPECIES.find(e=>"mallard"===e.id),a=e.BIRD_SPECIES.find(e=>"northern-pintail"===e.id);expect(t).toBeDefined(),expect(a).toBeDefined()})}),describe("Landing Page Integration",()=>{it("is integrated in WETLANDS_DATA landing page dataset",()=>{const e=loadWetlandsLandingData().wetlands.find(e=>"hygam-wetland"===e.id);expect(e).toBeDefined(),expect(e.exploreUrl).toBe("../hygam-wetland-explorer/index.html")})})});